import {towerToBlocks,paintBuildingBlock} from './building-blocks.js?v=building-blocks-1';
export function mountBuildingBlockEditor(root,{get,set}){
 root.innerHTML=`<label>Construction method<select id="blockMode"><option value="tower">Tower parameters</option><option value="blocks">Paint a block layout</option></select></label><section id="blockWorkspace" hidden><p>Paint a height onto the footprint. Use 0 to erase. Drag across squares, or use arrow keys and Enter/Space. The footprint stays north-up while the preview rotates. Heights are floors.</p><div class="block-editor-controls"><label>Height brush (0–24)<input id="blockBrush" type="number" min="0" max="24" step="1" value="8"></label><button id="blockUndo">Undo layout edit</button><button id="blockFromTower">Use tower footprint</button><button id="blockClear">Clear footprint</button></div><div id="blockGrid" role="grid" aria-label="Building footprint, north at top" aria-rowcount="10" aria-colcount="10">${Array.from({length:10},(_,y)=>`<div role="row">${Array.from({length:10},(_,x)=>`<button type="button" role="gridcell" data-block-index="${y*10+x}" tabindex="${x===0&&y===0?0:-1}"></button>`).join('')}</div>`).join('')}</div><p id="blockStatus" role="status"></p></section>`;
 const $=id=>root.querySelector('#'+id),grid=$('blockGrid'),cells=[...grid.querySelectorAll('[data-block-index]')],history=[];let memory=null,active=0,stroke=null,strokeSaved=false;
 const isBlocks=()=>Array.isArray(get().blocks);
 function refresh(){const blocks=get().blocks; $('blockMode').value=blocks?'blocks':'tower';$('blockWorkspace').hidden=!blocks;for(const id of ['designFloors','designWidth','designDepth','designRoof'])document.getElementById(id).disabled=!!blocks;$('blockUndo').disabled=!history.length;if(!blocks)return;cells.forEach((cell,i)=>{const h=blocks[i];cell.textContent=h||'·';cell.setAttribute('aria-label',`Column ${i%10+1}, row ${Math.floor(i/10)+1}: ${h} floors`);cell.tabIndex=i===active?0:-1;cell.style.background=`hsl(172 20% ${94-h*1.7}%)`;cell.style.color=h>14?'#fff':'#17382f';});$('blockStatus').textContent=blocks.some(h=>h)?`${blocks.filter(h=>h).length} occupied squares · tallest section ${Math.max(...blocks)} floors. Changes are a draft until applied.`:'Empty footprint. Paint at least one square before applying or exporting.';}
 function remember(){history.push([...get().blocks]);if(history.length>20)history.shift();}
 function replace(blocks,save=true){if(save)remember();memory=[...blocks];set({...get(),blocks});refresh();}
 function brush(){const n=Number($('blockBrush').value);if($('blockBrush').value.trim()===''||!Number.isInteger(n)||n<0||n>24){$('blockStatus').textContent='Choose a whole height from 0 to 24.';return null;}return n;}
 function paint(index,drag=false){if(!isBlocks())return;const height=brush();if(height===null||get().blocks[index]===height)return;if(!drag||!strokeSaved){remember();strokeSaved=true;}replace(paintBuildingBlock(get().blocks,index%10,Math.floor(index/10),height),false);}
 $('blockMode').onchange=()=>{if($('blockMode').value==='blocks'){set({...get(),blocks:memory?[...memory]:towerToBlocks(get())});}else{memory=get().blocks?[...get().blocks]:memory;const next={...get()};delete next.blocks;set(next);}history.length=0;refresh();};
 $('blockUndo').onclick=()=>{if(history.length)replace(history.pop(),false);};$('blockClear').onclick=()=>replace(Array(100).fill(0));$('blockFromTower').onclick=()=>replace(towerToBlocks(get()));
 grid.onpointerdown=event=>{if(event.button!==0)return;const cell=event.target.closest('[data-block-index]');if(!cell)return;event.preventDefault();stroke=event.pointerId;strokeSaved=false;active=Number(cell.dataset.blockIndex);cell.focus({preventScroll:true});grid.setPointerCapture(event.pointerId);paint(active,true);refresh();};
 grid.onpointermove=event=>{if(stroke!==event.pointerId)return;const cell=document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-block-index]');if(cell&&grid.contains(cell))paint(Number(cell.dataset.blockIndex),true);};
 grid.onpointerup=grid.onpointercancel=()=>{stroke=null;strokeSaved=false;};
 grid.onclick=event=>{if(event.detail!==0)return;const cell=event.target.closest('[data-block-index]');if(cell){active=Number(cell.dataset.blockIndex);paint(active);}};
 grid.onkeydown=event=>{const moves={ArrowLeft:-1,ArrowRight:1,ArrowUp:-10,ArrowDown:10};if(!(event.key in moves))return;event.preventDefault();const cell=event.target.closest('[data-block-index]');if(cell)active=Number(cell.dataset.blockIndex);const next=active+moves[event.key];if(next<0||next>=100||event.key==='ArrowLeft'&&active%10===0||event.key==='ArrowRight'&&active%10===9)return;active=next;refresh();cells[active].focus();};
 return {reset(){history.length=0;memory=get().blocks?[...get().blocks]:null;stroke=null;refresh();},refresh};
}
